using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Look for Csc tasks to get commandline/source info
var tasks = build.FindChildrenRecursive<Task>();
foreach (var t in tasks)
{
    if (t.Name == "Csc")
    {
        var proj = t.GetNearestParent<Project>();
        Console.WriteLine($"\n=== Csc in: {proj?.Name} ===");
        Console.WriteLine($"CommandLine: {t.CommandLineArguments?.Substring(0, Math.Min(t.CommandLineArguments?.Length ?? 0, 2000))}");
    }
}

// Also look for SourceFiles in the embedded files
Console.WriteLine("\n=== EMBEDDED FILES ===");
var sourceFiles = build.FindChildrenRecursive<SourceFile>();
foreach (var sf in sourceFiles)
{
    Console.WriteLine($"SourceFile: {sf.Name}, HasContent: {!string.IsNullOrEmpty(sf.Value)}");
    if (!string.IsNullOrEmpty(sf.Value))
    {
        Console.WriteLine(sf.Value.Substring(0, Math.Min(sf.Value.Length, 500)));
    }
}

// Check SourceFilesGroup
var items = build.FindChildrenRecursive<Item>();
foreach (var item in items)
{
    if (item.Name != null && item.Name.EndsWith(".cs") && item.Name.Contains("UserService"))
    {
        Console.WriteLine($"\nItem: {item.Name}");
        var parent = item.Parent;
        Console.WriteLine($"  Parent: {parent?.GetType().Name} - {(parent as NamedNode)?.Name}");
    }
}
EOF
